import { readFile, writeFile, rename, mkdir } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { randomUUID } from 'node:crypto'

export function createStore(file) {
  let books = null

  async function load() {
    if (books) return books
    try {
      books = JSON.parse(await readFile(file, 'utf8'))
    } catch (err) {
      if (err.code !== 'ENOENT') throw err
      books = []
    }
    return books
  }

  async function save() {
    await mkdir(dirname(file), { recursive: true })
    const tmp = join(dirname(file), `.${Date.now()}.tmp`)
    await writeFile(tmp, JSON.stringify(books, null, 2))
    await rename(tmp, file)
  }

  return {
    async all() {
      return load()
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null
    },

    async add({ title, author, notes = '' }) {
      await load()
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        finished: false,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      }
      books.push(book)
      await save()
      return book
    },

    async finish(id) {
      const book = await this.get(id)
      if (!book) return null
      book.finished = true
      book.finishedAt = new Date().toISOString()
      await save()
      return book
    },

    async updateNotes(id, notes) {
      const book = await this.get(id)
      if (!book) return null
      book.notes = notes
      await save()
      return book
    },
  }
}

import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { createStore } from './lib/store.js'

const store = createStore(new URL('./data/books.json', import.meta.url).pathname)
const PORT = process.env.PORT ?? 3000

const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[c])

const page = (title, body) => `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Reading List</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <main>
    <header>
      <h1><a href="/">Reading List</a></h1>
      <a class="button" href="/books/new">+ Add book</a>
    </header>
    ${body}
  </main>
</body>
</html>`

const bookRow = (b) => `
  <li>
    <a href="/books/${b.id}">${escapeHtml(b.title)}</a>
    <span class="author">${escapeHtml(b.author)}</span>
  </li>`

async function homePage() {
  const books = await store.all()
  const reading = books.filter((b) => !b.finished)
  const finished = books.filter((b) => b.finished)
  return page('Home', `
    <h2>Currently reading</h2>
    ${reading.length ? `<ul>${reading.map(bookRow).join('')}</ul>` : '<p class="empty">Nothing on the go.</p>'}
    <h2>Finished</h2>
    ${finished.length ? `<ul>${finished.map(bookRow).join('')}</ul>` : '<p class="empty">Nothing finished yet.</p>'}
  `)
}

const newBookPage = () =>
  page('Add a book', `
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="4"></textarea></label>
      <button type="submit">Add book</button>
    </form>
  `)

const bookPage = (b) =>
  page(b.title, `
    <h2>${escapeHtml(b.title)}</h2>
    <p class="author">by ${escapeHtml(b.author)}</p>
    <p class="status">${b.finished ? 'Finished' : 'Currently reading'}</p>
    <h3>Notes</h3>
    <form method="post" action="/books/${b.id}/notes">
      <textarea name="notes" rows="6">${escapeHtml(b.notes)}</textarea>
      <button type="submit">Save notes</button>
    </form>
    ${b.finished ? '' : `
    <form method="post" action="/books/${b.id}/finish">
      <button type="submit">Mark as finished</button>
    </form>`}
    <p class="share">Share this book: <a href="/books/${b.id}">/books/${b.id}</a></p>
  `)

const notFoundPage = () => page('Not found', '<h2>404 — book not found</h2>')

async function readBody(req) {
  let body = ''
  for await (const chunk of req) body += chunk
  return new URLSearchParams(body)
}

function redirect(res, location) {
  res.writeHead(303, { location })
  res.end()
}

function html(res, content, status = 200) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' })
  res.end(content)
}

export const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost')
    const path = url.pathname

    if (req.method === 'GET' && path === '/') return html(res, await homePage())
    if (req.method === 'GET' && path === '/books/new') return html(res, newBookPage())
    if (req.method === 'GET' && path === '/style.css') {
      res.writeHead(200, { 'content-type': 'text/css' })
      return res.end(await readFile(new URL('./public/style.css', import.meta.url)))
    }

    const bookMatch = path.match(/^\/books\/([\w-]+)$/)
    if (req.method === 'GET' && bookMatch) {
      const book = await store.get(bookMatch[1])
      return book ? html(res, bookPage(book)) : html(res, notFoundPage(), 404)
    }

    if (req.method === 'POST' && path === '/books') {
      const form = await readBody(req)
      const title = form.get('title')?.trim()
      const author = form.get('author')?.trim()
      if (!title || !author) return redirect(res, '/books/new')
      const book = await store.add({ title, author, notes: form.get('notes') ?? '' })
      return redirect(res, `/books/${book.id}`)
    }

    const actionMatch = path.match(/^\/books\/([\w-]+)\/(finish|notes)$/)
    if (req.method === 'POST' && actionMatch) {
      const [, id, action] = actionMatch
      const book =
        action === 'finish'
          ? await store.finish(id)
          : await store.updateNotes(id, (await readBody(req)).get('notes') ?? '')
      return book ? redirect(res, `/books/${id}`) : html(res, notFoundPage(), 404)
    }

    html(res, notFoundPage(), 404)
  } catch (err) {
    console.error(err)
    html(res, page('Error', '<h2>Something went wrong</h2>'), 500)
  }
})

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/^\//, ''))) {
  server.listen(PORT, () => console.log(`Reading list running at http://localhost:${PORT}`))
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, sans-serif;
  background: #f7f5f0;
  color: #222;
}

main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 2rem 1rem;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid #222;
  padding-bottom: 0.5rem;
  margin-bottom: 1.5rem;
}

h1 { font-size: 1.4rem; margin: 0; }
h1 a { color: inherit; text-decoration: none; }
h2 { font-size: 1.1rem; margin-top: 1.5rem; }

ul { list-style: none; padding: 0; }
li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.5rem 0.75rem;
  background: #fff;
  border: 1px solid #ddd;
  border-radius: 6px;
  margin-bottom: 0.5rem;
}
li a { font-weight: 600; color: #1a4f8a; text-decoration: none; }
li a:hover { text-decoration: underline; }

.author { color: #666; }
.empty { color: #888; font-style: italic; }
.status { color: #555; }

form { margin: 1rem 0; }
label { display: block; margin-bottom: 0.75rem; font-weight: 600; }
input, textarea {
  display: block;
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.5rem;
  font: inherit;
  font-weight: 400;
  border: 1px solid #bbb;
  border-radius: 6px;
  background: #fff;
}

button, .button {
  font: inherit;
  padding: 0.45rem 1rem;
  background: #222;
  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: none;
}
button:hover, .button:hover { background: #444; }

.share { color: #777; font-size: 0.85rem; margin-top: 2rem; }
.share a { color: #1a4f8a; word-break: break-all; }

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createStore } from '../lib/store.js'

let dir, file, store

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'))
  file = join(dir, 'books.json')
  store = createStore(file)
})

afterEach(() => rm(dir, { recursive: true, force: true }))

describe('store', () => {
  it('starts empty when the file does not exist', async () => {
    expect(await store.all()).toEqual([])
  })

  it('adds a book as currently reading', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
    expect(book.finished).toBe(false)
    expect(await store.get(book.id)).toMatchObject({ title: 'Dune', author: 'Frank Herbert' })
  })

  it('persists books across store instances (restart)', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
    const reloaded = createStore(file)
    expect(await reloaded.get(book.id)).toMatchObject({ title: 'Dune' })
  })

  it('marks a book finished', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
    const finished = await store.finish(book.id)
    expect(finished.finished).toBe(true)
    expect(finished.finishedAt).toBeTruthy()
  })

  it('updates notes', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
    await store.updateNotes(book.id, 'great so far')
    expect((await store.get(book.id)).notes).toBe('great so far')
  })

  it('returns null for unknown ids', async () => {
    expect(await store.get('nope')).toBeNull()
    expect(await store.finish('nope')).toBeNull()
  })
})

describe('server', () => {
  let base, server

  beforeEach(async () => {
    process.env.BOOKS_FILE = file
    const mod = await import(`../server.js?t=${Date.now()}`)
    server = mod.server
    await new Promise((resolve) => server.listen(0, resolve))
    base = `http://localhost:${server.address().port}`
  })

  afterEach(() => new Promise((resolve) => server.close(resolve)))

  it('shows empty reading lists on the home page', async () => {
    const res = await fetch(`${base}/`)
    const body = await res.text()
    expect(res.status).toBe(200)
    expect(body).toContain('Currently reading')
    expect(body).toContain('Finished')
    expect(body).toContain('Nothing on the go.')
  })

  it('adds a book and redirects to its shareable page', async () => {
    const res = await fetch(`${base}/books`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ title: 'Dune', author: 'Frank Herbert', notes: 'spicy' }),
      redirect: 'manual',
    })
    expect(res.status).toBe(303)
    const location = res.headers.get('location')
    expect(location).toMatch(/^\/books\/[\w-]+$/)

    const page = await (await fetch(`${base}${location}`)).text()
    expect(page).toContain('Dune')
    expect(page).toContain('Frank Herbert')
    expect(page).toContain('spicy')
    expect(page).toContain('Currently reading')
  })

  it('marks a book finished and lists it under Finished', async () => {
    const res = await fetch(`${base}/books`, {
      method: 'POST',
      body: new URLSearchParams({ title: 'Dune', author: 'Frank Herbert' }),
      redirect: 'manual',
    })
    const location = res.headers.get('location')

    const fin = await fetch(`${base}${location}/finish`, { method: 'POST', redirect: 'manual' })
    expect(fin.status).toBe(303)

    const home = await (await fetch(`${base}/`)).text()
    const finishedSection = home.split('<h2>Finished</h2>')[1]
    expect(finishedSection).toContain('Dune')
  })

  it('rejects books without title or author', async () => {
    const res = await fetch(`${base}/books`, {
      method: 'POST',
      body: new URLSearchParams({ title: '', author: '' }),
      redirect: 'manual',
    })
    expect(res.headers.get('location')).toBe('/books/new')
  })

  it('404s for unknown books', async () => {
    const res = await fetch(`${base}/books/does-not-exist`)
    expect(res.status).toBe(404)
  })

  it('escapes HTML in book fields', async () => {
    const res = await fetch(`${base}/books`, {
      method: 'POST',
      body: new URLSearchParams({ title: '<script>x</script>', author: 'A' }),
      redirect: 'manual',
    })
    const page = await (await fetch(`${base}${res.headers.get('location')}`)).text()
    expect(page).not.toContain('<script>x</script>')
    expect(page).toContain('&lt;script&gt;')
  })
})

